
# Task 1: Plotting with Pandas

import sqlite3
import pandas as pd
import matplotlib.pyplot as plt

# Connecting to the database
conn = sqlite3.connect("./db/lesson.db")
cursor = conn.cursor()

# Query to calculate the total revenue generated by each employee by joining the employees, orders, line_items, and products tables, and then grouping by employee_id to get the total revenue for each employee.
query = """
SELECT last_name, SUM(price * quantity) AS revenue 
FROM employees e JOIN orders o 
ON e.employee_id = o.employee_id 
JOIN line_items l ON o.order_id = l.order_id 
JOIN products p ON l.product_id = p.product_id 
GROUP BY e.employee_id;


"""

# Execute and fetch results
cursor.execute(query)
results = cursor.fetchall()
print(results)

conn.close()

# Bar Plot
results_df = pd.DataFrame(results, columns=["Last Name", "Revenue"])
results_df.plot(x="Last Name", y="Revenue", kind="bar", color="skyblue", title="Employee Revenue")
plt.show()





